public static long maxOperationsOnGraph(int N, int M, int[][] edges, int[] W, long[] A) {
    long operations = 0;
    boolean piecesExist = true;

    while (piecesExist) {
        piecesExist = false;
        for (int i = 0; i < N; i++) {
            if (A[i] > 0) {
                piecesExist = true;
                A[i]--;
                long sumWeights = 0;
                for (int[] edge : edges) {
                    int u = edge[0];
                    int v = edge[1];
                    if (u == i || v == i) {
                        int adjacentVertex = (u == i) ? v : u;
                        if (sumWeights + W[adjacentVertex] < W[i]) {
                            sumWeights += W[adjacentVertex];
                            A[adjacentVertex]++;
                        }
                    }
                }
                operations++;
            }
        }
    }
    return operations;
}
